preConditionHook:
// UpperBandTouchHigherHigh (Brian's notes ON-64-a, #64). A touch is a bar
// whose high reaches the upper band (el_ge); a run of consecutive touch bars
// is ONE touch (an episode). This bar touches, and its high exceeds the
// highest high of the PREVIOUS episode, and no earlier bar of the current
// episode already did: long, once per episode. Short mirrors on lower-band
// touches (low <= lower band) making a lower low. Both episodes must lie in
// bars 0 .. lookback - 1; an episode cut by the window edge counts with the
// bars inside it.
// The bands are BollingerBandCross's construction, open-coded at each offset
// ii so a past bar's band is computed from price as it stood on that bar (EL's
// BollingerBand is fresh per bar; reading a stored band variable at [ii]
// would compare against its zero fill during warm-up): Average(close, length)
// summed NEWEST-FIRST, POPULATION StdDev, upper = avg + numDevs x sd, lower =
// avg + (-numDevs) x sd. `bollingerband` VERIFIED; do not reorder the loops.
// Phases walking back from bar 1: 0 = still in the current episode, 1 = the
// gap, 2 = in the previous episode, 3 = done.
upPhase = 0;
dnPhase = 0;
haveCurHi = false;
havePrevHi = false;
haveCurLo = false;
havePrevLo = false;
curHi = 0.0;
prevHi = 0.0;
curLo = 0.0;
prevLo = 0.0;
touchUp0 = false;
touchDn0 = false;
for (int ii = 0; ii <= (int)lookback - 1; ++ii) {
    bbAvg = 0.0;
    for (int jj = 0; jj < (int)length; ++jj) {
        bbAvg += close[ii + jj];
    }
    bbAvg /= (int)length;
    bbSd = 0.0;
    for (int jj = 0; jj < (int)length; ++jj) {
        bbDev = close[ii + jj] - bbAvg;
        bbSd += bbDev * bbDev;
    }
    bbSd = std::sqrt(bbSd / (int)length);
    upperBand = bbAvg + numDevs * bbSd;
    lowerBand = bbAvg + (-numDevs) * bbSd;
    touchUp = el_ge(high[ii], upperBand);
    touchDn = el_le(low[ii], lowerBand);
    if (ii == 0) {
        touchUp0 = touchUp;
        touchDn0 = touchDn;
    } else {
        if (upPhase == 0) {
            if (touchUp) {
                if (!haveCurHi || el_gt(high[ii], curHi)) curHi = high[ii];
                haveCurHi = true;
            } else upPhase = 1;
        } else if (upPhase == 1) {
            if (touchUp) {
                upPhase = 2;
                prevHi = high[ii];
                havePrevHi = true;
            }
        } else if (upPhase == 2) {
            if (touchUp) {
                if (el_gt(high[ii], prevHi)) prevHi = high[ii];
            } else upPhase = 3;
        }
        if (dnPhase == 0) {
            if (touchDn) {
                if (!haveCurLo || el_lt(low[ii], curLo)) curLo = low[ii];
                haveCurLo = true;
            } else dnPhase = 1;
        } else if (dnPhase == 1) {
            if (touchDn) {
                dnPhase = 2;
                prevLo = low[ii];
                havePrevLo = true;
            }
        } else if (dnPhase == 2) {
            if (touchDn) {
                if (el_lt(low[ii], prevLo)) prevLo = low[ii];
            } else dnPhase = 3;
        }
    }
}
